function getTileList() {
  const list = [];
  for (const z in TILE_INDEX)
    for (const x in TILE_INDEX[z])
      for (const y of TILE_INDEX[z][x])
        list.push(`tiles/${z}/${x}/${y}.jpg`);
  return list;
}
